/* Печеньки для Lampa, v0.1.1. ES5, без внешних зависимостей. */
(function () {
    'use strict';

    if (window.Pechenki) return;
    var L = window.Lampa;
    if (!L || !L.Listener) return;

    var component = 'pechenki';
    var version = '0.1.1';
    var masterKey = 'pechenki_enabled';
    var features = [];
    var ready = false;
    var icon = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none">' +
        '<path d="M21 12a4 4 0 0 1-5-5 4 4 0 0 1-4-4 9 9 0 1 0 9 9Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/>' +
        '<g fill="currentColor"><circle cx="8" cy="8" r="1.2"/><circle cx="7" cy="14" r="1.2"/><circle cx="12" cy="12" r="1.2"/><circle cx="13" cy="17" r="1.2"/></g></svg>';

    function boolean(value) {
        return value === true || value === 'true' || value === 1 || value === '1';
    }

    function escapeHtml(value) {
        return String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }

    function find(id) {
        for (var i = 0; i < features.length; i++) {
            if (features[i].id === id) return features[i];
        }
        return null;
    }

    function enabled(id) {
        if (!boolean(L.Storage.get(masterKey, true))) return false;
        if (typeof id === 'undefined') return true;
        var feature = find(id);
        return !!feature && boolean(L.Storage.get(feature.key, feature.defaultEnabled));
    }

    function applyFeature(feature) {
        var next = enabled(feature.id);
        if (next === feature.active) return;
        try {
            if (next) feature.enable();
            else feature.disable();
            feature.active = next;
        }
        catch (error) {
            // A failed feature must not stop the remaining features from updating.
            console.error('[Печеньки] ' + feature.id, error);
            if (next) {
                try { feature.disable(); } catch (cleanupError) {
                    console.error('[Печеньки] cleanup ' + feature.id, cleanupError);
                }
                L.Storage.set(feature.key, false);
            }
            if (L.Noty) L.Noty.show('Печеньки: ошибка функции «' + feature.title + '».');
        }
    }

    function sync() {
        if (!ready) return;
        for (var i = 0; i < features.length; i++) applyFeature(features[i]);
    }

    function addToggle(feature) {
        L.SettingsApi.addParam({
            component: component,
            param: {name: feature.key, type: 'trigger', default: feature.defaultEnabled},
            field: {name: escapeHtml(feature.title), description: escapeHtml(feature.description)},
            onChange: sync
        });
    }

    function registerFeature(definition) {
        if (!definition || !/^[a-z][a-z0-9_]*$/.test(definition.id) ||
            !definition.title || typeof definition.enable !== 'function' ||
            typeof definition.disable !== 'function') {
            throw new Error('Печеньки: нужны id, title, enable и disable.');
        }
        if (find(definition.id)) throw new Error('Печеньки: повторный id ' + definition.id);
        var feature = {
            id: definition.id,
            key: 'pechenki_feature_' + definition.id,
            title: definition.title,
            description: definition.description || '',
            defaultEnabled: boolean(definition.defaultEnabled),
            enable: definition.enable,
            disable: definition.disable,
            active: false
        };
        features.push(feature);
        if (ready) {
            addToggle(feature);
            applyFeature(feature);
        }
    }

    function setEnabled(id, value) {
        var feature = typeof id === 'undefined' ? null : find(id);
        if (typeof id !== 'undefined' && !feature) throw new Error('Печеньки: неизвестная функция ' + id);
        L.Storage.set(feature ? feature.key : masterKey, boolean(value));
        sync();
    }

    function open() {
        // Open the native panel first: Settings.create alone does not show its layer.
        L.Controller.toggle('settings');
        L.Settings.create(component);
    }

    function createFavoriteFeature() {
        var entries = [];
        var style = null;
        var running = false;
        // Embedded promotional poster: no image-server dependency on the TV.
        var poster = 'data:image/jpeg;base64,';
        var selector = '.pechenki-favorite-home .pechenki-favorite-card';

        function decorateCard(card) {
            if (!card.querySelector('.card__img') || !card.querySelector('.card__view')) return;
            var data = card.card_data;
            if (data && (data.media_type === 'person' || (data.profile_path && !data.poster_path))) return;
            if (card.classList.contains('card--folder') || card.classList.contains('card--more')) return;
            // Keep movie objects, original text, images, and click handlers intact.
            card.classList.add('pechenki-favorite-card');
            if (!card.querySelector('.pechenki-favorite-poster')) {
                var overlay = window.document.createElement('div');
                overlay.className = 'pechenki-favorite-poster';
                overlay.setAttribute('aria-hidden', 'true');
                card.querySelector('.card__view').appendChild(overlay);
            }
        }

        function scan(node) {
            if (!node || node.nodeType !== 1) return;
            if (node.classList.contains('card')) decorateCard(node);
            var cards = node.querySelectorAll('.card');
            for (var i = 0; i < cards.length; i++) decorateCard(cards[i]);
        }

        function detach(entry) {
            entry.observer.disconnect();
            entry.root.classList.remove('pechenki-favorite-home');
            var cards = entry.root.querySelectorAll('.pechenki-favorite-card');
            for (var i = 0; i < cards.length; i++) cards[i].classList.remove('pechenki-favorite-card');
            var overlays = entry.root.querySelectorAll('.pechenki-favorite-poster');
            for (var j = 0; j < overlays.length; j++) {
                if (overlays[j].parentNode) overlays[j].parentNode.removeChild(overlays[j]);
            }
        }

        function attach(object) {
            if (!object || object.component !== 'main' || !object.activity) return;
            var root = object.activity.render(true);
            if (root && root.jquery) root = root[0];
            if (!root || !root.querySelectorAll) return;
            for (var i = 0; i < entries.length; i++) {
                if (entries[i].root === root) { scan(root); return; }
            }
            root.classList.add('pechenki-favorite-home');
            scan(root);
            var observer = new window.MutationObserver(function (mutations) {
                if (!running) return;
                for (var m = 0; m < mutations.length; m++) {
                    // Ignore removals and attribute changes (lazy loading/focus).
                    for (var n = 0; n < mutations[m].addedNodes.length; n++) {
                        var node = mutations[m].addedNodes[n];
                        scan(node);
                        // Some themes append the contents after an empty card.
                        var parent = node.parentElement;
                        while (parent && parent !== root) {
                            if (parent.classList.contains('card')) { decorateCard(parent); break; }
                            parent = parent.parentElement;
                        }
                    }
                }
            });
            observer.observe(root, {childList: true, subtree: true});
            entries.push({root: root, object: object, observer: observer});
        }

        function onActivity(event) {
            if (!running || event.component !== 'main') return;
            if (event.type === 'destroy') {
                for (var i = entries.length - 1; i >= 0; i--) {
                    if (entries[i].object === event.object) {
                        detach(entries[i]);
                        entries.splice(i, 1);
                    }
                }
            }
            else attach(event.object);
        }

        function enable() {
            if (running) return;
            if (!window.document || !window.MutationObserver || !L.Activity) {
                throw new Error('Нет поддержки визуального режима.');
            }
            style = window.document.createElement('style');
            style.id = 'pechenki-favorite-style';
            style.textContent =
                selector + ' .pechenki-favorite-poster{position:absolute;top:0;left:0;right:0;bottom:0;' +
                'z-index:2;border-radius:1em;pointer-events:none;background:#fff url("' + poster + '") center center/contain no-repeat;}' +
                selector + ' .card__title,' + selector + ' .card__promo-title,' + selector + ' .card__age{position:relative;visibility:hidden!important;}' +
                selector + ' .card__title,' + selector + ' .card__promo-title{height:1.2em;min-height:1.2em;max-height:1.2em;}' +
                selector + ' .card__title:after,' + selector + ' .card__promo-title:after{content:"Ранетки";visibility:visible;position:absolute;left:0;right:0;top:0;}' +
                selector + ' .card__age:after{content:"2008";visibility:visible;position:absolute;left:0;top:0;}' +
                selector + ' .card__promo{z-index:3;pointer-events:none;}' +
                selector + ' .card__promo-text{display:none!important;}';
            (window.document.head || window.document.body).appendChild(style);
            running = true;
            L.Listener.follow('activity', onActivity);
            attach(L.Activity.active());
        }

        function disable() {
            running = false;
            L.Listener.remove('activity', onActivity);
            for (var i = 0; i < entries.length; i++) detach(entries[i]);
            entries = [];
            if (style && style.parentNode) style.parentNode.removeChild(style);
            style = null;
        }

        return {enable: enable, disable: disable};
    }

    function init() {
        if (ready) return;
        if (!L.SettingsApi || !L.Settings || !L.Storage || !L.Controller) {
            console.error('[Печеньки] Недоступен API настроек Lampa.');
            return;
        }
        L.SettingsApi.addComponent({component: component, name: 'Печеньки', icon: icon});
        L.SettingsApi.addParam({
            component: component,
            param: {name: masterKey, type: 'trigger', default: true},
            field: {
                name: 'Включить наши функции',
                description: 'Общий выключатель. Выбор отдельных функций сохраняется.'
            },
            onChange: sync
        });
        L.SettingsApi.addParam({
            component: component,
            param: {name: 'pechenki_info', type: 'title'},
            field: {
                name: 'Наши настройки',
                description: 'Включай то, что нравится. Все изменения можно отключить.'
            }
        });
        for (var i = 0; i < features.length; i++) addToggle(features[i]);
        L.SettingsApi.addParam({
            component: component,
            param: {name: 'pechenki_version', type: 'title'},
            field: {name: 'Версия ' + version}
        });

        if (L.Menu && typeof L.Menu.addButton === 'function') {
            L.Menu.addButton(icon, 'Печеньки', open).attr('data-action', 'pechenki');
        }
        else {
            var button = window.$('<li class="menu__item selector" data-action="pechenki">' +
                '<div class="menu__ico">' + icon + '</div><div class="menu__text">Печеньки</div></li>');
            button.on('hover:enter', open);
            window.$('.menu .menu__list').eq(0).append(button);
        }
        ready = true;
        L.Listener.remove('app', onApp);
        sync();
    }

    function onApp(event) {
        if (event.type === 'ready') init();
    }

    window.Pechenki = {
        version: version,
        registerFeature: registerFeature,
        isEnabled: enabled,
        setEnabled: setEnabled,
        open: open
    };

    var favorite = createFavoriteFeature();
    registerFeature({
        id: 'my_favorite',
        title: 'Мое любимое',
        description: 'Для особого настроения.',
        defaultEnabled: false,
        enable: favorite.enable,
        disable: favorite.disable
    });

    if (window.appready) init();
    else L.Listener.follow('app', onApp);
}());
